import { qrSvg } from "./qr-engine.js";
import {
  auth,QRAJN,DEFAULT_BRANDING,DEFAULT_SETTINGS,waitForAuthReady,onAccountChanged,signUpEmail,signInEmail,signInGoogle,
  resetPassword,signOutAccount,getWorkspaceState,subscribeWorkspace,createQr,updateQr,deleteQr as removeQr,
  saveBranding as persistBranding,saveSettings as persistSettings,uploadBrandLogo,resetWorkspace,resolvePublicLink,trackPublicScan,
  saveBusinessProfile,deleteBusinessProfile,uploadBusinessAsset,resolveBusinessProfile,trackBusinessEvent,submitBusinessLead,normalizeSlug
} from "./firebase-backend.js";

const app=document.querySelector("#app");
const toastRoot=document.querySelector("#toast-root");
let session=null,liveUnsubscribe=null,authUnsubscribe=null;
let state={qrs:[],events:[],branding:{...DEFAULT_BRANDING},settings:{...DEFAULT_SETTINGS},profiles:[],businessEvents:[],leads:[],qrLeads:[]};

const icons={
 qr:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 14h3v3h-3zm4 4h3v3h-3m0-7h3v3m-7 4h3"/></svg>`,
 chart:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19V9m6 10V5m6 14v-7m4 7H2"/></svg>`,
 plus:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>`,
 building:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 21V7l8-4 8 4v14M8 10h2m4 0h2M8 14h2m4 0h2M9 21v-3h6v3"/></svg>`,
 palette:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3a9 9 0 1 0 0 18h1.5a2 2 0 0 0 0-4H12a2 2 0 0 1 0-4h2a7 7 0 0 0-2-10Z"/></svg>`,
 gear:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.5-2-3.4-2.4 1A7 7 0 0 0 15 6l-.3-2.6h-4L10.4 6A7 7 0 0 0 8 7.1l-2.4-1-2 3.4 2 1.5a7 7 0 0 0 0 2l-2 1.5 2 3.4 2.4-1A7 7 0 0 0 10.4 18l.3 2.6h4L15 18a7 7 0 0 0 2.4-1.1l2.4 1 2-3.4-2-1.5c.1-.3.2-.7.2-1Z"/></svg>`,
 link:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 13a5 5 0 0 0 7.1.1l2-2A5 5 0 0 0 12 4l-1 1M14 11a5 5 0 0 0-7.1-.1l-2 2A5 5 0 0 0 12 20l1-1"/></svg>`,
 users:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="8" r="4"/><path d="M2 21a7 7 0 0 1 14 0m1-12a4 4 0 0 1 0 8m0 0a6 6 0 0 1 5 4"/></svg>`,
 phone:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 4h4l2 5-3 2a16 16 0 0 0 5 5l2-3 5 2v4c0 1-1 2-2 2C10 21 3 14 3 6c0-1 1-2 2-2Z"/></svg>`,
 pin:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/></svg>`,
 mail:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></svg>`,
 external:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 3h7v7M10 14 21 3M21 13v7a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h7"/></svg>`
};

function esc(s=""){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
function attr(s=""){return esc(s).replace(/`/g,"&#96;");}
function toast(message,kind="default"){const el=document.createElement("div");el.className=`toast ${kind}`;el.setAttribute("role","status");el.textContent=message;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3600);}
function friendlyError(error){
 const code=String(error?.code||"");
 const map={"auth/email-already-in-use":"An account already exists with this email.","auth/invalid-email":"Enter a valid email address.","auth/invalid-credential":"Email or password is incorrect.","auth/wrong-password":"Email or password is incorrect.","auth/weak-password":"Use at least 6 characters.","auth/too-many-requests":"Too many attempts. Try again later.","auth/popup-closed-by-user":"Google sign-in was closed.","auth/operation-not-allowed":"This sign-in method is not enabled yet.","auth/unauthorized-domain":"This domain is not authorized for account sign-in.","auth/network-request-failed":"Network error. Check your internet connection.","PERMISSION_DENIED":"You do not have permission to perform this action. Check the QR AJN database rules."};
 return map[code]||String(error?.message||"Something went wrong.").replace(/Firebase/gi,"account service");
}
function brandMark(){return `<span class="brandmark"><img src="/assets/qr-ajn-logo.svg" alt=""></span>`;}
function productBrand(){return `${brandMark()}<span>QR <b>AJN</b></span>`;}
function fmtDate(v){if(!v)return "—";const d=new Date(v);return Number.isNaN(d.valueOf())?"—":new Intl.DateTimeFormat("en-IN",{day:"2-digit",month:"short",year:"numeric"}).format(d);}
function ago(v){const d=new Date(v);if(Number.isNaN(d.valueOf()))return "—";let s=Math.max(0,Math.round((Date.now()-d)/1000));if(s<60)return `${s}s ago`;if(s<3600)return `${Math.floor(s/60)}m ago`;if(s<86400)return `${Math.floor(s/3600)}h ago`;return `${Math.floor(s/86400)}d ago`;}
function safeName(s){return String(s||"QR_AJN").replace(/[^a-z0-9_-]+/gi,"_").slice(0,80)||"QR_AJN";}
function route(path){if(protectedPath(path)&&!session)path="/auth";history.pushState({},"",path);render();}
window.route=route;window.addEventListener("popstate",render);document.addEventListener("click",e=>{const a=e.target.closest("a[data-route]");if(a){e.preventDefault();route(a.getAttribute("href"));}});
function protectedPath(p=location.pathname){return ["/dashboard","/qr-codes","/branding","/create","/settings","/business-profiles","/business/new"].includes(p)||/^\/qr\/[^/]+$/.test(p)||/^\/business\/[^/]+$/.test(p);}
function current(path){return location.pathname===path?"active":"";}
function userInitial(){return (session?.user?.displayName||session?.user?.email||"U").trim().charAt(0).toUpperCase()||"U";}
function shell(content){return `<div class="app-shell">${appNav()}${content}</div>`;}
function connectLive(){if(liveUnsubscribe)liveUnsubscribe();if(!session?.user)return;liveUnsubscribe=subscribeWorkspace(session.user,next=>{state=next;if(!document.activeElement?.matches("input,textarea,select"))render();});}
async function loadState(){if(session?.user)state=await getWorkspaceState(session.user);}

function appNav(){
 const who=esc(session?.user?.displayName||session?.user?.email||"Workspace");
 return `<nav class="topnav"><a class="brand" href="/dashboard" data-route>${productBrand()}</a><div class="navlinks">
 <a class="${current("/dashboard")}" href="/dashboard" data-route>Dashboard</a><a class="${location.pathname.startsWith("/qr")||current("/create")?"active":""}" href="/qr-codes" data-route>QR Codes</a><a class="${location.pathname.startsWith("/business")?"active":""}" href="/business-profiles" data-route>Business Profiles</a><a class="${current("/branding")}" href="/branding" data-route>Branding</a><a class="${current("/settings")}" href="/settings" data-route>Settings</a></div>
 <div class="nav-actions"><span class="workspace-user">${who}</span><button class="btn primary small" onclick="route('/create')">${icons.plus} Create</button><button class="avatar" onclick="signOutNow()" title="Sign out">${userInitial()}</button></div></nav>
 <nav class="mobile-bottom-nav" aria-label="Mobile navigation"><a class="${current("/dashboard")}" href="/dashboard" data-route><span>${icons.chart}</span><b>Home</b></a><a class="${location.pathname.startsWith("/qr")?"active":""}" href="/qr-codes" data-route><span>${icons.qr}</span><b>QRs</b></a><a class="mobile-create" href="/create" data-route><span>${icons.plus}</span><b>Create</b></a><a class="${location.pathname.startsWith("/business")?"active":""}" href="/business-profiles" data-route><span>${icons.building}</span><b>Business</b></a><a class="${current("/settings")}" href="/settings" data-route><span>${icons.gear}</span><b>Settings</b></a></nav>`;
}
function landingNav(){return `<nav class="topnav landing-nav"><a class="brand" href="/" data-route>${productBrand()}</a><div class="navlinks"><a href="#features">Features</a><a href="#business">Business Profiles</a><a href="#how">How it works</a><a href="#included">Included</a></div><div class="nav-actions"><button class="btn ghost sign-in" onclick="route('${session?"/dashboard":"/auth"}')">${session?"Dashboard":"Sign in"}</button><button class="btn primary" onclick="route('${session?"/create":"/auth"}')">Create QR</button></div></nav>`;}

function landing(){
 const featureCards=[
  [icons.qr,"Dynamic QR","Keep the same printed QR while changing its destination."],[icons.chart,"Real-time insights","See real scans, devices, browsers and campaign activity."],[icons.building,"Business Profiles","Publish a mini business website with products, offers and enquiries."],[icons.link,"Smart routing","Expiry, schedule, UTM and targeting rules travel with each dynamic QR."],[icons.users,"Lead capture","Collect consent-based enquiries from campaigns and business profiles."],[icons.palette,"Brand control","Use your colors, logo and optional profile branding without a paywall."]
 ];
 return `<div class="app-shell">${landingNav()}<main><section class="hero"><div class="hero-copy"><span class="eyebrow">Dynamic QR + Business Profiles</span><h1>One QR. <span class="gradient-text">A complete business journey.</span></h1><p>Create QR codes, publish mobile-first business profiles, update destinations without reprinting, and understand what customers actually do.</p><div class="hero-actions"><button class="btn primary large" onclick="route('${session?"/create":"/auth"}')">Create your QR ${icons.external}</button><button class="btn large" onclick="document.querySelector('#business').scrollIntoView({behavior:'smooth'})">Explore Business Profiles</button></div><div class="trust"><span>All core tools included</span><span>Optional branding</span><span>No login required to scan</span></div></div><div class="hero-visual"><img src="/assets/business-profile-illustration.svg" alt="QR AJN business profile preview"></div></section>
 <section class="landing-section" id="features"><div class="center-title"><span class="kicker">EVERYTHING CONNECTED</span><h2>From scan to customer action</h2><p>QR creation, profiles, leads and analytics live in one simple workspace.</p></div><div class="feature-cards">${featureCards.map(x=>`<article class="card feature-card"><div class="fi">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join("")}</div></section>
 <section class="business-showcase" id="business"><div><span class="kicker">BUSINESS PROFILE</span><h2>Your mini website behind one permanent QR.</h2><p>Add contact actions, products, services, offers, hours, social links and an enquiry form. Update the profile later without changing the printed QR.</p><div class="check-grid"><span>Call & WhatsApp</span><span>Directions</span><span>Products & services</span><span>Offers</span><span>Opening hours</span><span>Lead capture</span></div><button class="btn primary" onclick="route('${session?"/business/new":"/auth"}')">Create Business Profile</button></div><img src="/assets/business-profile-illustration.svg" alt="Business profile mobile interface"></section>
 <section class="landing-section" id="how"><div class="center-title"><span class="kicker">SIMPLE FLOW</span><h2>Publish in minutes</h2></div><div class="how-grid">${[["01","Create","Choose a QR type or business profile."],["02","Customize","Set destination, style and campaign controls."],["03","Publish","Download the QR or share your profile link."],["04","Improve","Edit content and follow real-time results."]].map(x=>`<div class="card how-card"><b>${x[0]}</b><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join("")}</div></section>
 <section class="landing-section" id="included"><div class="included-card"><div><span class="kicker">ALL CORE FEATURES INCLUDED</span><h2>No feature-wall inside the QR workspace.</h2><p>Domain settings, branding, expiry, schedules, password protection, lead capture, targeting, UTM parameters and labels are available in the product. Secure server features require the deployment environment to be configured correctly.</p></div><button class="btn primary" onclick="route('${session?"/dashboard":"/auth"}')">Open workspace</button></div></section>
 </main><footer class="footer"><a class="brand" href="/" data-route>${productBrand()}</a><span>Dynamic QR, business identity and real-time customer journeys.</span></footer></div>`;
}

let authMode="signin";
function authPage(){return `<div class="auth-shell"><a class="brand auth-brand" href="/" data-route>${productBrand()}</a><main class="auth-card card"><span class="auth-badge">SECURE ACCOUNT ACCESS</span><h1 id="auth-heading">Welcome back</h1><p class="subtitle" id="auth-subtitle">Sign in to manage QR codes, business profiles and analytics.</p><div class="auth-tabs"><button class="auth-tab active" onclick="setAuthMode('signin',this)">Sign in</button><button class="auth-tab" onclick="setAuthMode('signup',this)">Create account</button></div><form id="auth-form" onsubmit="submitAuth(event)"><div class="field auth-name" hidden><label>Full name</label><input id="auth-name" autocomplete="name" placeholder="Your name"></div><div class="field"><label>Email</label><input id="auth-email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field auth-password"><label>Password</label><input id="auth-password" type="password" autocomplete="current-password" minlength="6" placeholder="At least 6 characters" required></div><button class="btn primary full auth-submit" type="submit">Sign in</button></form><button class="auth-forgot" onclick="setAuthMode('reset')">Forgot password?</button><div class="auth-divider"><span>or</span></div><button class="btn full google-btn" onclick="googleSignIn()">Continue with Google</button><p class="auth-terms">Your workspace is private to your account. Public business profiles open without requiring customers to sign in.</p></main></div>`;}
window.setAuthMode=(mode)=>{authMode=mode;const heading=document.querySelector("#auth-heading"),sub=document.querySelector("#auth-subtitle"),name=document.querySelector(".auth-name"),pass=document.querySelector(".auth-password"),submit=document.querySelector(".auth-submit"),forgot=document.querySelector(".auth-forgot");document.querySelectorAll(".auth-tab").forEach((b,i)=>b.classList.toggle("active",(mode==="signin"&&i===0)||(mode==="signup"&&i===1)));if(mode==="signup"){heading.textContent="Create your account";sub.textContent="Start creating QR codes and business profiles.";name.hidden=false;pass.hidden=false;submit.textContent="Create account";forgot.hidden=true;}else if(mode==="reset"){heading.textContent="Reset password";sub.textContent="We will send a secure reset link to your email.";name.hidden=true;pass.hidden=true;submit.textContent="Send reset link";forgot.hidden=true;}else{heading.textContent="Welcome back";sub.textContent="Sign in to manage QR codes, business profiles and analytics.";name.hidden=true;pass.hidden=false;submit.textContent="Sign in";forgot.hidden=false;}};
window.submitAuth=async e=>{e.preventDefault();const email=document.querySelector("#auth-email").value.trim(),password=document.querySelector("#auth-password")?.value||"",name=document.querySelector("#auth-name")?.value||"";try{if(authMode==="reset"){await resetPassword(email);toast("Password reset link sent.","success");setAuthMode("signin");return;}if(authMode==="signup")await signUpEmail(email,password,name);else await signInEmail(email,password);toast("Signed in successfully.","success");route("/dashboard");}catch(error){toast(friendlyError(error),"error");}};
window.googleSignIn=async()=>{try{await signInGoogle();toast("Signed in successfully.","success");route("/dashboard");}catch(e){toast(friendlyError(e),"error");}};
window.signOutNow=async()=>{try{await signOutAccount();route("/");}catch(e){toast(friendlyError(e),"error");}};

function qrEvents(id){return state.events.filter(e=>e.qr_id===id);}
function profileEvents(id,type=""){return state.businessEvents.filter(e=>e.profileId===id&&(!type||e.eventType===type));}
function profileLeads(id){return state.leads.filter(e=>e.profileId===id);}
function dashboard(){
 const scans=state.events.length,profileViews=state.businessEvents.filter(e=>e.eventType==="view").length,leads=state.leads.length+state.qrLeads.length,actions=state.businessEvents.filter(e=>["call","whatsapp","directions","website"].includes(e.eventType)).length;
 return shell(`<main class="container"><div class="section-head"><div><span class="kicker">OVERVIEW</span><h1 class="page-title">Your QR AJN workspace</h1><p class="subtitle">Live QR campaigns and business profile activity in one place.</p></div><div class="head-actions"><button class="btn" onclick="route('/business/new')">${icons.building} Business Profile</button><button class="btn primary" onclick="route('/create')">${icons.plus} New QR</button></div></div><div class="grid4"><div class="card metric"><span>${icons.qr}</span><strong>${state.qrs.length}</strong><small>QR Codes</small></div><div class="card metric"><span>${icons.chart}</span><strong>${scans}</strong><small>QR Scans</small></div><div class="card metric"><span>${icons.building}</span><strong>${profileViews}</strong><small>Profile Views</small></div><div class="card metric"><span>${icons.users}</span><strong>${leads}</strong><small>Leads</small></div></div><div class="dashboard-grid"><section class="card panel"><div class="panel-head"><div><h2>Recent QR activity</h2><p>Scans update automatically.</p></div><a href="/qr-codes" data-route>View QR codes</a></div>${state.events.slice(0,6).map(e=>`<div class="activity-row"><span class="activity-icon">${icons.qr}</span><div><b>${esc(state.qrs.find(q=>q.id===e.qr_id)?.name||"QR scan")}</b><small>${esc(e.device||"Device")} · ${esc(e.browser||"")}</small></div><time>${ago(e.when)}</time></div>`).join("")||`<div class="empty compact">No scans yet. Create a dynamic QR and scan it from another device.</div>`}</section><section class="card panel"><div class="panel-head"><div><h2>Business activity</h2><p>Customer actions from public profiles.</p></div><a href="/business-profiles" data-route>Profiles</a></div><div class="mini-stats"><div><b>${state.profiles.length}</b><span>Profiles</span></div><div><b>${actions}</b><span>Actions</span></div><div><b>${leads}</b><span>Leads</span></div></div>${state.leads.slice(0,4).map(l=>`<div class="lead-row"><div><b>${esc(l.name)}</b><small>${esc(l.phone)} · ${esc(state.profiles.find(p=>p.id===l.profileId)?.name||"")}</small></div><time>${ago(Number(l.createdAt||0))}</time></div>`).join("")||`<div class="empty compact">Publish a business profile to start collecting enquiries.</div>`}</section></div></main>`);
}

function qrList(){
 const labels=[...new Set(state.qrs.flatMap(q=>q.labels||[]))].sort();
 return shell(`<main class="container"><div class="section-head"><div><span class="kicker">QR LIBRARY</span><h1 class="page-title">QR Codes</h1><p class="subtitle">Search, organize and update every QR from one place.</p></div><button class="btn primary" onclick="route('/create')">${icons.plus} New QR</button></div><div class="toolbar"><input class="search" id="qr-search" placeholder="Search QR codes" oninput="filterQrList()"><select class="select" id="qr-label-filter" onchange="filterQrList()"><option value="">All labels</option>${labels.map(l=>`<option>${esc(l)}</option>`).join("")}</select></div><div class="qr-grid" id="qr-grid">${state.qrs.map(q=>qrCard(q)).join("")||`<div class="empty-card"><h3>No QR codes yet</h3><p>Create your first QR and it will appear here instantly.</p><button class="btn primary" onclick="route('/create')">Create QR</button></div>`}</div></main>`);
}
function qrCard(q){const scans=qrEvents(q.id).length;return `<article class="card qr-list-card" data-name="${attr((q.name||"").toLowerCase())}" data-labels="${attr((q.labels||[]).join("|").toLowerCase())}"><div class="qr-thumb">${qrSvg(shortLink(q),{size:94,margin:q.design?.quietZone||4,fg:q.design?.foreground||"#0f172a",bg:q.design?.background||"#fff",ec:q.design?.errorCorrection||"M"})}</div><div class="qr-card-copy"><div class="row-between"><div><span class="status-dot ${q.is_active===false?"off":""}"></span><small>${q.is_dynamic!==false?"Dynamic":"Static"}</small></div><span>${scans} scans</span></div><h3>${esc(q.name)}</h3><p>${q.is_dynamic!==false?esc(q.destination_url):esc(q.type?.toUpperCase())}</p><div class="label-list">${(q.labels||[]).slice(0,4).map(l=>`<span>${esc(l)}</span>`).join("")}</div><div class="card-actions"><button class="btn small" onclick="route('/qr/${q.id}')">Manage</button><button class="btn small ghost" onclick="copyText('${attr(shortLink(q))}')">Copy link</button></div></div></article>`;}
window.filterQrList=()=>{const s=(document.querySelector("#qr-search")?.value||"").toLowerCase(),l=(document.querySelector("#qr-label-filter")?.value||"").toLowerCase();document.querySelectorAll(".qr-list-card").forEach(el=>{el.hidden=!(el.dataset.name.includes(s)&&(!l||el.dataset.labels.split("|").includes(l)));});};

function shortLink(q){if(q?.is_dynamic===false)return q.content||"";return `${QRAJN.productionOrigin.replace(/\/$/,"")}/r/${q.short_id}`;}
function qv(q,path,def=""){const parts=path.split(".");let x=q;for(const p of parts){x=x?.[p];if(x===undefined||x===null)return def;}return x;}
function checked(v){return v?"checked":"";}
function qrDetail(id){
 const q=state.qrs.find(x=>x.id===id);if(!q)return shell(`<main class="container"><div class="empty-card"><h2>QR code not found</h2><button class="btn" onclick="route('/qr-codes')">Back</button></div></main>`);
 const dynamic=q.is_dynamic!==false,events=qrEvents(id),encoded=shortLink(q),rules=q.smartTargeting?.rules||[];
 const getRule=field=>rules.find(r=>r.field===field)||{};
 return shell(`<main class="container"><div class="breadcrumb"><a href="/qr-codes" data-route>QR Codes</a><span>/</span><b>${esc(q.name)}</b></div><div class="detail-grid"><aside class="card qr-card"><div class="qr-box">${qrSvg(encoded,{size:230,margin:q.design?.quietZone||4,fg:q.design?.foreground||"#0f172a",bg:q.design?.background||"#fff",ec:q.design?.errorCorrection||"M"})}</div><h2>${esc(q.name)}</h2><span class="status-chip ${q.is_active===false?"inactive":""}">${q.is_active===false?"Inactive":"Active"} · ${dynamic?"Dynamic":"Static"}</span><div class="stat-pair"><div><strong>${dynamic?events.length:"—"}</strong><span>Scans</span></div><div><strong>${events[0]?ago(events[0].when):"—"}</strong><span>Last scan</span></div></div><div class="download-grid"><button class="btn small" onclick="downloadQR('${q.id}','png')">PNG</button><button class="btn small" onclick="downloadQR('${q.id}','svg')">SVG</button><button class="btn small" onclick="downloadQR('${q.id}','jpg')">JPG</button><button class="btn small" onclick="downloadQR('${q.id}','webp')">WebP</button></div>${dynamic?`<button class="btn full ghost" onclick="toggleQr('${q.id}')">${q.is_active===false?"Activate":"Deactivate"}</button>`:""}<button class="btn danger full" onclick="deleteQR('${q.id}')">Delete QR</button></aside><section class="detail-main">
 <div class="card settings-card"><div class="panel-head"><div><h2>${dynamic?"Redirect destination":"Encoded content"}</h2><p>${dynamic?"Change the destination without replacing the QR image.":"Static QR content is embedded directly."}</p></div></div>${dynamic?`<div class="inline-form"><input class="search" id="dest-${q.id}" value="${attr(q.destination_url)}"><button class="btn primary" onclick="updateDestination('${q.id}')">Save destination</button></div><div class="copy-line"><code>${esc(encoded)}</code><button class="btn small" onclick="copyText('${attr(encoded)}')">Copy</button></div>`:`<div class="payload-box">${esc(q.content)}</div>`}</div>
 ${dynamic?advancedQrPanel(q,getRule):""}
 ${dynamic?analyticsPanel(q,events):`<div class="card panel"><h2>Static QR</h2><p class="muted">Static QR codes do not contact QR AJN when scanned, so scan analytics cannot be measured reliably.</p></div>`}
 </section></div></main>`);
}
function advancedQrPanel(q,getRule){return `<div class="card settings-card"><div class="panel-head"><div><h2>Campaign controls</h2><p>All controls are available. Save once to update the live dynamic link.</p></div><button class="btn primary" onclick="saveAdvancedQr('${q.id}')">Save controls</button></div><div class="accordion-grid">
 <details open><summary>Labels & organization</summary><div class="setting-body"><div class="field"><label>Labels</label><input id="adv-labels" value="${attr((q.labels||[]).join(", "))}" placeholder="Marketing, Store, Instagram"><small>Separate labels with commas.</small></div></div></details>
 <details><summary>Expiry</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-expiry-enabled" ${checked(qv(q,"expiry.enabled",false))}><span>Enable expiry rules</span></label><div class="form-grid"><div class="field"><label>Expire at</label><input type="datetime-local" id="adv-expiry-at" value="${attr(toLocalInput(qv(q,"expiry.at","")))}"></div><div class="field"><label>Maximum scans</label><input type="number" min="0" id="adv-max-scans" value="${Number(qv(q,"expiry.maxScans",0))}" placeholder="0 = unlimited"></div></div><div class="field"><label>Expired fallback URL</label><input id="adv-expired-url" value="${attr(qv(q,"expiry.expiredDestination",""))}" placeholder="https://example.com/expired"></div></div></details>
 <details><summary>Schedule</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-schedule-enabled" ${checked(qv(q,"schedule.enabled",false))}><span>Use a start/end schedule</span></label><div class="form-grid"><div class="field"><label>Starts</label><input type="datetime-local" id="adv-schedule-start" value="${attr(toLocalInput(qv(q,"schedule.startAt","")))}"></div><div class="field"><label>Ends</label><input type="datetime-local" id="adv-schedule-end" value="${attr(toLocalInput(qv(q,"schedule.endAt","")))}"></div></div><div class="field"><label>Outside schedule URL</label><input id="adv-schedule-url" value="${attr(qv(q,"schedule.outsideDestination",""))}" placeholder="https://example.com/closed"></div></div></details>
 <details><summary>Password</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-password-enabled" ${checked(q.passwordProtected)}><span>Require a password before redirect</span></label><div class="field"><label>Set / change password</label><input type="password" id="adv-password" minlength="6" placeholder="Leave blank to keep the current password"><small>Password verification is enforced by the secure redirect service after deployment environment setup.</small></div></div></details>
 <details><summary>Lead capture</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-lead-enabled" ${checked(qv(q,"leadCapture.enabled",false))}><span>Collect an enquiry before redirect</span></label><div class="field"><label>Form title</label><input id="adv-lead-title" value="${attr(qv(q,"leadCapture.title","Send an enquiry"))}"></div><div class="field"><label>Fields</label><div class="check-row">${["name","phone","email","message"].map(f=>`<label><input type="checkbox" class="adv-lead-field" value="${f}" ${(qv(q,"leadCapture.fields",["name","phone"])).includes(f)?"checked":""} ${["name","phone"].includes(f)?"disabled":""}> ${f[0].toUpperCase()+f.slice(1)}</label>`).join("")}</div></div><div class="field"><label>Consent text</label><input id="adv-consent" value="${attr(qv(q,"leadCapture.consentText","I agree to share these details with this business."))}"></div></div></details>
 <details><summary>Smart targeting</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-target-enabled" ${checked(qv(q,"smartTargeting.enabled",false))}><span>Route scanners to different destinations</span></label><div class="form-grid"><div class="field"><label>Android URL</label><input id="adv-android-url" value="${attr(getRule("device:android").destination||"")}"></div><div class="field"><label>iPhone / iPad URL</label><input id="adv-ios-url" value="${attr(getRule("device:ios").destination||"")}"></div><div class="field"><label>Desktop URL</label><input id="adv-desktop-url" value="${attr(getRule("device:desktop").destination||"")}"></div><div class="field"><label>Fallback URL</label><input id="adv-target-fallback" value="${attr(qv(q,"smartTargeting.fallbackDestination",""))}"></div></div><div class="form-grid"><div class="field"><label>Country code</label><input id="adv-country" value="${attr(getRule("country").value||"")}" placeholder="IN"></div><div class="field"><label>Country destination</label><input id="adv-country-url" value="${attr(getRule("country").destination||"")}"></div><div class="field"><label>Language</label><input id="adv-language" value="${attr(getRule("language").value||"")}" placeholder="te"></div><div class="field"><label>Language destination</label><input id="adv-language-url" value="${attr(getRule("language").destination||"")}"></div></div></div></details>
 <details><summary>UTM parameters</summary><div class="setting-body"><label class="switch-row"><input type="checkbox" id="adv-utm-enabled" ${checked(qv(q,"utm.enabled",false))}><span>Append campaign parameters</span></label><div class="form-grid"><div class="field"><label>Source</label><input id="adv-utm-source" value="${attr(qv(q,"utm.source",""))}" placeholder="qrajn"></div><div class="field"><label>Medium</label><input id="adv-utm-medium" value="${attr(qv(q,"utm.medium",""))}" placeholder="qr"></div><div class="field"><label>Campaign</label><input id="adv-utm-campaign" value="${attr(qv(q,"utm.campaign",""))}"></div><div class="field"><label>Content</label><input id="adv-utm-content" value="${attr(qv(q,"utm.content",""))}"></div></div></div></details>
 <details><summary>Domain</summary><div class="setting-body"><div class="field"><label>Custom domain</label><input id="adv-domain" value="${attr(qv(q,"customDomain.host",""))}" placeholder="qr.yourbusiness.com"><small>Default links continue to use qrajn.online. Custom domains require DNS verification and attachment to the deployment.</small></div><div class="domain-status"><span>${qv(q,"customDomain.verified",false)?"Verified":"Not verified"}</span><button class="btn small" onclick="verifyDomain('${q.id}')">Check DNS</button></div></div></details>
 </div></div>`;}
function analyticsPanel(q,events){const qrLeadCount=state.qrLeads.filter(l=>l.qrId===q.id).length;const devices=events.reduce((a,e)=>(a[e.device||"Other"]=(a[e.device||"Other"]||0)+1,a),{});return `<div class="card analytics-panel"><div class="panel-head"><div><h2>Scan analytics</h2><p>${events.length} recorded scans</p></div><button class="btn small" onclick="downloadCsv('${q.id}')">Export CSV</button></div><div class="analytics-summary"><div><b>${events.length}</b><span>Total scans</span></div><div><b>${Object.keys(devices).length}</b><span>Device groups</span></div><div><b>${qrLeadCount}</b><span>Leads</span></div></div><div class="scan-list">${events.slice(0,12).map(e=>`<div class="scan-row"><div><b>${esc(e.device||"Unknown")}</b><small>${esc(e.browser||"")} · ${esc(e.os||"")} · ${esc(e.timezone||"")}</small></div><time>${ago(e.when)}</time></div>`).join("")||`<div class="empty compact">No scans yet.</div>`}</div></div>`;}

function toLocalInput(value){if(!value)return "";const d=new Date(value);if(Number.isNaN(d.valueOf()))return "";const z=n=>String(n).padStart(2,"0");return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`;}
function inputIso(id){const value=document.querySelector(id)?.value;return value?new Date(value).toISOString():"";}
window.saveAdvancedQr=async id=>{try{
 const q=state.qrs.find(x=>x.id===id);if(!q)return;
 const rules=[];const pushRule=(field,value,destination)=>{if(destination)rules.push({field,operator:"equals",value,destination});};
 pushRule("device:android","android",document.querySelector("#adv-android-url").value.trim());
 pushRule("device:ios","ios",document.querySelector("#adv-ios-url").value.trim());
 pushRule("device:desktop","desktop",document.querySelector("#adv-desktop-url").value.trim());
 pushRule("country",document.querySelector("#adv-country").value.trim().toUpperCase(),document.querySelector("#adv-country-url").value.trim());
 pushRule("language",document.querySelector("#adv-language").value.trim().toLowerCase(),document.querySelector("#adv-language-url").value.trim());
 const leadEnabled=document.querySelector("#adv-lead-enabled").checked;
 const leadFields=[...new Set(["name","phone",...[...document.querySelectorAll(".adv-lead-field:checked")].map(x=>x.value)])];
 const passwordEnabled=document.querySelector("#adv-password-enabled").checked,newPassword=document.querySelector("#adv-password").value;
 if(passwordEnabled&&!q.passwordProtected&&!newPassword)return toast("Set a password before enabling password protection.","error");
 if(passwordEnabled&&newPassword){
   const token=await session.user.getIdToken();
   const r=await fetch("/api/qr-secret",{method:"POST",headers:{"content-type":"application/json","authorization":`Bearer ${token}`},body:JSON.stringify({qrId:id,password:newPassword})});
   if(!r.ok){const body=await r.json().catch(()=>({}));throw new Error(body.error||"Password security endpoint is not configured on this deployment.");}
 }
 const patch={labels:document.querySelector("#adv-labels").value,
   expiry:{enabled:document.querySelector("#adv-expiry-enabled").checked,at:inputIso("#adv-expiry-at"),maxScans:Number(document.querySelector("#adv-max-scans").value||0),expiredDestination:document.querySelector("#adv-expired-url").value.trim()},
   schedule:{enabled:document.querySelector("#adv-schedule-enabled").checked,startAt:inputIso("#adv-schedule-start"),endAt:inputIso("#adv-schedule-end"),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||"Asia/Kolkata",outsideDestination:document.querySelector("#adv-schedule-url").value.trim()},
   passwordProtected:passwordEnabled,
   leadCapture:{enabled:leadEnabled,title:document.querySelector("#adv-lead-title").value.trim(),fields:leadFields,consentText:document.querySelector("#adv-consent").value.trim()},
   smartTargeting:{enabled:document.querySelector("#adv-target-enabled").checked,fallbackDestination:document.querySelector("#adv-target-fallback").value.trim(),rules},
   utm:{enabled:document.querySelector("#adv-utm-enabled").checked,source:document.querySelector("#adv-utm-source").value.trim(),medium:document.querySelector("#adv-utm-medium").value.trim(),campaign:document.querySelector("#adv-utm-campaign").value.trim(),content:document.querySelector("#adv-utm-content").value.trim()},
   customDomain:{...(q.customDomain||{}),host:document.querySelector("#adv-domain").value.trim()}
 };
 await updateQr(session.user,id,patch);
 if(!passwordEnabled&&q.passwordProtected){const token=await session.user.getIdToken();await fetch("/api/qr-secret",{method:"DELETE",headers:{"content-type":"application/json","authorization":`Bearer ${token}`},body:JSON.stringify({qrId:id})}).catch(()=>{});}
 toast("Campaign controls saved.","success");await loadState();render();
}catch(e){toast(friendlyError(e),"error")}};
window.verifyDomain=async id=>{try{const host=document.querySelector("#adv-domain").value.trim().replace(/^https?:\/\//,"").replace(/\/$/,"");if(!host)return toast("Enter a custom domain first.","error");const token=await session.user.getIdToken();const r=await fetch("/api/domain-check",{method:"POST",headers:{"content-type":"application/json","authorization":`Bearer ${token}`},body:JSON.stringify({qrId:id,host})});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||"Domain verification could not be completed.");await updateQr(session.user,id,{customDomain:{host,verificationToken:body.token,verified:!!body.verified}});toast(body.verified?"Domain ownership verified.":`Add TXT record: ${body.record}`,body.verified?"success":"default");await loadState();render();}catch(e){toast(friendlyError(e),"error");}};
window.toggleQr=async id=>{try{const q=state.qrs.find(x=>x.id===id);await updateQr(session.user,id,{is_active:q.is_active===false});toast(q.is_active===false?"QR activated.":"QR deactivated.","success");}catch(e){toast(friendlyError(e),"error");}};
window.updateDestination=async id=>{try{const value=document.querySelector(`#dest-${CSS.escape(id)}`).value.trim();if(!/^https?:\/\//i.test(value))return toast("Enter a complete http:// or https:// URL.","error");await updateQr(session.user,id,{destination_url:value});toast("Destination updated instantly.","success");}catch(e){toast(friendlyError(e),"error");}};
window.deleteQR=async id=>{if(!confirm("Delete this QR code and its scan history?"))return;try{await removeQr(session.user,id);toast("QR code deleted.","success");route("/qr-codes");}catch(e){toast(friendlyError(e),"error");}};

const createModel={type:"url",fg:"#0f172a",bg:"#ffffff",ec:"M",margin:4};
function createPage(){const types=["url","text","email","sms","phone","wifi","vcard","location"];return shell(`<main class="container"><div class="section-head"><div><span class="kicker">QR CREATOR</span><h1 class="page-title">Create a QR Code</h1><p class="subtitle">Choose a type, preview it and save it to your workspace.</p></div></div><div class="creator-layout"><section class="card form-card"><div class="field"><label>Name</label><input id="qr-name" placeholder="Summer campaign"></div><div class="field"><label>QR type</label><div class="type-grid">${types.map(t=>`<button class="type-card ${createModel.type===t?"active":""}" onclick="selectType('${t}')">${typeLabel(t)}</button>`).join("")}</div></div><div id="type-fields">${typeFields(createModel.type)}</div><div class="field"><label>Labels</label><input id="qr-labels" placeholder="Marketing, Store, Poster"></div><div class="design-grid"><div class="field"><label>Foreground</label><input type="color" id="qr-fg" value="${createModel.fg}" oninput="updateCreatePreview()"></div><div class="field"><label>Background</label><input type="color" id="qr-bg" value="${createModel.bg}" oninput="updateCreatePreview()"></div><div class="field"><label>Error correction</label><select id="qr-ec" onchange="updateCreatePreview()"><option>L</option><option selected>M</option><option>Q</option><option>H</option></select></div></div><button class="btn primary full large" onclick="saveQRCode()">Create QR Code</button></section><aside class="card creator-preview"><span class="kicker">LIVE PREVIEW</span><div id="create-qr-preview"></div><h3 id="preview-caption">Dynamic · destination can be changed later</h3><p>High contrast and a clear quiet zone improve real-world scanning.</p></aside></div></main>`);}
function typeLabel(t){return ({url:"Website",text:"Text",email:"Email",sms:"SMS",phone:"Phone",wifi:"Wi-Fi",vcard:"Contact",location:"Location"})[t]||t;}
function typeFields(t){const m={url:`<div class="field"><label>Destination URL</label><input id="qr-content" type="url" placeholder="https://example.com" oninput="updateCreatePreview()"></div>`,text:`<div class="field"><label>Text</label><textarea id="qr-content" placeholder="Your message" oninput="updateCreatePreview()"></textarea></div>`,email:`<div class="field"><label>Email address</label><input id="qr-content" type="email" placeholder="hello@example.com" oninput="updateCreatePreview()"></div>`,sms:`<div class="form-grid"><div class="field"><label>Phone</label><input id="qr-phone" placeholder="+91..."></div><div class="field"><label>Message</label><input id="qr-message" placeholder="Hello"></div></div>`,phone:`<div class="field"><label>Phone number</label><input id="qr-content" placeholder="+91..." oninput="updateCreatePreview()"></div>`,wifi:`<div class="form-grid"><div class="field"><label>Network name</label><input id="qr-ssid" placeholder="WiFi name"></div><div class="field"><label>Password</label><input id="qr-wifi-pass" placeholder="Password"></div></div>`,vcard:`<div class="form-grid"><div class="field"><label>Name</label><input id="qr-vcard-name"></div><div class="field"><label>Phone</label><input id="qr-vcard-phone"></div><div class="field"><label>Email</label><input id="qr-vcard-email"></div><div class="field"><label>Company</label><input id="qr-vcard-company"></div></div>`,location:`<div class="form-grid"><div class="field"><label>Latitude</label><input id="qr-lat" placeholder="17.3850"></div><div class="field"><label>Longitude</label><input id="qr-lng" placeholder="78.4867"></div></div>`};return m[t]||m.url;}
function contentForType(){const val=id=>document.querySelector(id)?.value.trim()||"";switch(createModel.type){case"url":return val("#qr-content");case"text":return val("#qr-content");case"email":return `mailto:${encodeURIComponent(val("#qr-content"))}`;case"sms":return `sms:${val("#qr-phone")}?body=${encodeURIComponent(val("#qr-message"))}`;case"phone":return `tel:${val("#qr-content")}`;case"wifi":return `WIFI:T:WPA;S:${val("#qr-ssid").replace(/([\\;,:"])/g,"\\$1")};P:${val("#qr-wifi-pass").replace(/([\\;,:"])/g,"\\$1")};;`;case"vcard":return `BEGIN:VCARD\nVERSION:3.0\nFN:${val("#qr-vcard-name")}\nORG:${val("#qr-vcard-company")}\nTEL:${val("#qr-vcard-phone")}\nEMAIL:${val("#qr-vcard-email")}\nEND:VCARD`;case"location":return `geo:${val("#qr-lat")},${val("#qr-lng")}`;default:return val("#qr-content");}}
window.selectType=t=>{createModel.type=t;render();setTimeout(updateCreatePreview,0);};
window.updateCreatePreview=()=>{const box=document.querySelector("#create-qr-preview");if(!box)return;createModel.fg=document.querySelector("#qr-fg")?.value||createModel.fg;createModel.bg=document.querySelector("#qr-bg")?.value||createModel.bg;createModel.ec=document.querySelector("#qr-ec")?.value||createModel.ec;let value;try{value=createModel.type==="url"?`${QRAJN.productionOrigin}/r/preview`:contentForType()||"QR AJN";box.innerHTML=qrSvg(value,{size:270,margin:createModel.margin,fg:createModel.fg,bg:createModel.bg,ec:createModel.ec});}catch(e){box.innerHTML=`<div class="qr-preview-error">${esc(e.message)}</div>`;}};
window.saveQRCode=async()=>{try{const name=document.querySelector("#qr-name").value.trim()||"Untitled QR",raw=contentForType();if(!raw.trim())return toast("Add QR content first.","error");const isDynamic=createModel.type==="url";const q=await createQr(session.user,{name,type:createModel.type,content:raw,destination_url:isDynamic?raw:"",is_dynamic:isDynamic,labels:document.querySelector("#qr-labels").value,design:{foreground:document.querySelector("#qr-fg").value,background:document.querySelector("#qr-bg").value,errorCorrection:document.querySelector("#qr-ec").value,quietZone:4}});toast("QR code created.","success");route(`/qr/${q.id}`);}catch(e){toast(friendlyError(e),"error");}};

function brandingPage(){const b=state.branding;return shell(`<main class="container"><div class="section-head"><div><span class="kicker">BRANDING</span><h1 class="page-title">Scan page branding</h1><p class="subtitle">Branding is optional. Use the QR AJN default or apply your own identity.</p></div></div><div class="brand-grid"><section class="card form-card"><label class="switch-row"><input type="checkbox" id="brand-enabled" ${checked(b.enabled!==false)}><span>Use custom scan-page branding</span></label><div class="field"><label>Page title</label><input id="brand-title" value="${attr(b.title||"Thanks for scanning")}"></div><div class="form-grid"><div class="field"><label>Background</label><input type="color" id="brand-bg" value="${attr(b.background||"#f0fdfa")}" oninput="previewBrand()"></div><div class="field"><label>Accent</label><input type="color" id="brand-accent" value="${attr(b.accent||"#0f766e")}" oninput="previewBrand()"></div></div><div class="field"><label>Logo</label><input id="brand-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP up to 1 MB.</small></div><button class="btn primary full" onclick="saveBranding()">Save branding</button></section><aside class="card live-preview"><div class="scan-preview" id="brand-preview" style="background:${attr(b.background)}"><div class="preview-logo" id="brand-preview-logo" style="background:${attr(b.accent)}">${b.logo?`<img src="${attr(b.logo)}" alt="Brand logo">`:"A"}</div><span>QR AJN</span><h2 id="brand-preview-title">${esc(b.title)}</h2><p>Your destination opens after the QR scan is processed.</p><div class="preview-line" style="background:${attr(b.accent)}"></div></div></aside></div></main>`);}
window.previewBrand=()=>{const p=document.querySelector("#brand-preview");if(!p)return;p.style.background=document.querySelector("#brand-bg").value;document.querySelector("#brand-preview-logo").style.background=document.querySelector("#brand-accent").value;document.querySelector(".preview-line")?.style&&(document.querySelector(".preview-line").style.background=document.querySelector("#brand-accent").value);document.querySelector("#brand-preview-title").textContent=document.querySelector("#brand-title").value;};
window.saveBranding=async()=>{try{let logo=state.branding.logo||"";const file=document.querySelector("#brand-logo-file")?.files?.[0];if(file)logo=await uploadBrandLogo(session.user,file);state.branding=await persistBranding(session.user,{enabled:document.querySelector("#brand-enabled").checked,title:document.querySelector("#brand-title").value.trim()||"Thanks for scanning",background:document.querySelector("#brand-bg").value,accent:document.querySelector("#brand-accent").value,logo});toast("Branding saved.","success");render();}catch(e){toast(friendlyError(e),"error");}};

function businessProfilesPage(){return shell(`<main class="container"><div class="section-head"><div><span class="kicker">BUSINESS PROFILES</span><h1 class="page-title">Your public business pages</h1><p class="subtitle">A mobile-first mini website behind a permanent QR.</p></div><button class="btn primary" onclick="route('/business/new')">${icons.plus} New profile</button></div><div class="profile-grid">${state.profiles.map(p=>businessCard(p)).join("")||`<div class="empty-card"><img src="/assets/business-profile-illustration.svg" alt=""><h2>Create your first Business Profile</h2><p>Add products, services, offers, contact actions and an enquiry form.</p><button class="btn primary" onclick="route('/business/new')">Create profile</button></div>`}</div></main>`);}
function businessCard(p){const views=profileEvents(p.id,"view").length,leads=profileLeads(p.id).length;return `<article class="card business-card"><div class="business-cover" style="${p.cover?`background-image:url('${attr(p.cover)}')`:""}">${p.logo?`<img src="${attr(p.logo)}" alt="${attr(p.name)} logo">`:`<span>${esc((p.name||"B")[0])}</span>`}</div><div class="business-card-body"><div class="row-between"><span class="status-chip">${p.published?"Published":"Draft"}</span><small>${views} views · ${leads} leads</small></div><h2>${esc(p.name)}</h2><p>${esc(p.tagline||p.type)}</p><code>${QRAJN.productionOrigin}/b/${esc(p.slug)}</code><div class="card-actions"><button class="btn small primary" onclick="route('/business/${p.id}')">Edit</button><button class="btn small" onclick="window.open('/b/${p.slug}','_blank')">View</button><button class="btn small" onclick="downloadBusinessQr('${p.id}')">QR</button></div></div></article>`;}
function parseLines(value,type){return String(value||"").split(/\r?\n/).map((line,i)=>line.trim()).filter(Boolean).map((line,i)=>{const a=line.split("|").map(x=>x.trim());return type==="offer"?{id:`o${i+1}`,title:a[0],description:a[1]||"",expiresAt:a[2]||"",active:true}:{id:`${type[0]}${i+1}`,name:a[0],price:a[1]||"",description:a[2]||"",image:a[3]||"",available:true};});}
function formatLines(items,type){return (items||[]).map(x=>type==="offer"?[x.title||"",x.description||"",x.expiresAt||""].join(" | ").replace(/(?: \|)+$/," ").trim():[x.name||"",x.price||"",x.description||"",x.image||""].join(" | ").replace(/(?: \|)+$/," ").trim()).join("\n");}
function businessEditor(id){const p=id?state.profiles.find(x=>x.id===id):null;const x=p||{name:"",slug:"",type:"Shop",tagline:"",about:"",phone:"",whatsapp:"",email:"",website:"",address:"",mapsUrl:"",hours:"",logo:"",cover:"",brochure:"",googleReview:"",upi:"",whatsappMessage:"Hi, I found your business through QR AJN.",socials:{},products:[],services:[],offers:[],branding:{enabled:false,accent:"#0f766e",background:"#ffffff",buttonStyle:"soft",layout:"modern"},leadCapture:{enabled:true,title:"Send an enquiry",askEmail:false,askMessage:true},published:true};return shell(`<main class="container"><div class="breadcrumb"><a href="/business-profiles" data-route>Business Profiles</a><span>/</span><b>${p?esc(p.name):"New profile"}</b></div><div class="section-head"><div><span class="kicker">PROFILE BUILDER</span><h1 class="page-title">${p?"Edit Business Profile":"Create Business Profile"}</h1><p class="subtitle">Branding is optional. Start simple and add sections when you need them.</p></div>${p?`<button class="btn" onclick="window.open('/b/${p.slug}','_blank')">Open public page</button>`:""}</div><div class="business-editor"><section class="card form-card"><h2>Business details</h2><div class="form-grid"><div class="field"><label>Business name</label><input id="bp-name" value="${attr(x.name)}" oninput="suggestSlug()"></div><div class="field"><label>Business type</label><select id="bp-type">${["Shop","Restaurant","Professional","Freelancer","Doctor / Clinic","Hotel","School / Institute","Real Estate","Photographer","Digital Creator","Services Business","Agriculture / Farmer","Product Catalogue"].map(t=>`<option ${x.type===t?"selected":""}>${t}</option>`).join("")}</select></div></div><div class="field"><label>Public URL</label><div class="url-field"><span>qrajn.online/b/</span><input id="bp-slug" value="${attr(x.slug)}" placeholder="my-business"></div></div><div class="field"><label>Tagline</label><input id="bp-tagline" value="${attr(x.tagline)}" placeholder="Fresh farm vegetables · Vemulawada"></div><div class="field"><label>About</label><textarea id="bp-about" rows="4">${esc(x.about)}</textarea></div><h2>Contact & location</h2><div class="form-grid"><div class="field"><label>Phone</label><input id="bp-phone" value="${attr(x.phone)}"></div><div class="field"><label>WhatsApp</label><input id="bp-whatsapp" value="${attr(x.whatsapp)}"></div><div class="field"><label>Email</label><input id="bp-email" value="${attr(x.email)}"></div><div class="field"><label>Website</label><input id="bp-website" value="${attr(x.website)}"></div></div><div class="field"><label>Address</label><textarea id="bp-address">${esc(x.address)}</textarea></div><div class="form-grid"><div class="field"><label>Directions URL</label><input id="bp-maps" value="${attr(x.mapsUrl)}"></div><div class="field"><label>Opening hours</label><input id="bp-hours" value="${attr(x.hours)}" placeholder="Mon–Sat · 8 AM–8 PM"></div></div><div class="field"><label>WhatsApp default message</label><input id="bp-wa-message" value="${attr(x.whatsappMessage)}"></div><h2>Products, services & offers</h2><div class="field"><label>Products</label><textarea id="bp-products" rows="5" placeholder="Ridge Gourd | ₹60/kg | Fresh today | https://image-url">${esc(formatLines(x.products,"product"))}</textarea><small>One per line: Name | Price | Description | Image URL</small></div><div class="field"><label>Services</label><textarea id="bp-services" rows="4" placeholder="Color Xerox | ₹5/page | Same-day">${esc(formatLines(x.services,"service"))}</textarea><small>One per line: Name | Price | Description</small></div><div class="field"><label>Offers</label><textarea id="bp-offers" rows="4" placeholder="₹10 Cashback | On orders above ₹200 | 2026-08-31">${esc(formatLines(x.offers,"offer"))}</textarea><small>One per line: Title | Description | Expiry</small></div><h2>Links & actions</h2><div class="form-grid"><div class="field"><label>Brochure / menu URL</label><input id="bp-brochure" value="${attr(x.brochure)}"></div><div class="field"><label>Google Review URL</label><input id="bp-review" value="${attr(x.googleReview)}"></div><div class="field"><label>UPI ID</label><input id="bp-upi" value="${attr(x.upi)}" placeholder="name@bank"></div><div class="field"><label>Instagram URL</label><input id="bp-instagram" value="${attr(x.socials?.instagram||"")}"></div><div class="field"><label>Facebook URL</label><input id="bp-facebook" value="${attr(x.socials?.facebook||"")}"></div><div class="field"><label>YouTube URL</label><input id="bp-youtube" value="${attr(x.socials?.youtube||"")}"></div></div><h2>Branding (optional)</h2><label class="switch-row"><input type="checkbox" id="bp-brand-enabled" ${checked(x.branding?.enabled)}><span>Use custom colors for this profile</span></label><div class="form-grid"><div class="field"><label>Accent</label><input type="color" id="bp-accent" value="${attr(x.branding?.accent||"#0f766e")}"></div><div class="field"><label>Background</label><input type="color" id="bp-background" value="${attr(x.branding?.background||"#ffffff")}"></div></div><div class="form-grid"><div class="field"><label>Logo image</label><input id="bp-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><input id="bp-logo" type="hidden" value="${attr(x.logo)}"></div><div class="field"><label>Cover image</label><input id="bp-cover-file" type="file" accept="image/png,image/jpeg,image/webp"><input id="bp-cover" type="hidden" value="${attr(x.cover)}"></div></div><h2>Lead capture</h2><label class="switch-row"><input type="checkbox" id="bp-lead-enabled" ${checked(x.leadCapture?.enabled!==false)}><span>Show enquiry form</span></label><div class="form-grid"><label class="check-card"><input type="checkbox" id="bp-lead-email" ${checked(x.leadCapture?.askEmail)}><span>Ask for email</span></label><label class="check-card"><input type="checkbox" id="bp-lead-message" ${checked(x.leadCapture?.askMessage!==false)}><span>Ask for message</span></label></div><label class="switch-row"><input type="checkbox" id="bp-published" ${checked(x.published!==false)}><span>Publish profile</span></label><button class="btn primary full large" onclick="saveBusiness('${p?.id||""}')">${p?"Save changes":"Publish Business Profile"}</button>${p?`<button class="btn danger full" onclick="removeBusiness('${p.id}')">Delete profile</button>`:""}</section><aside class="card business-preview"><span class="kicker">PUBLIC PREVIEW</span>${miniProfilePreview(x)}</aside></div></main>`);}
function miniProfilePreview(p){return `<div class="phone-preview"><div class="phone-cover" style="${p.cover?`background-image:url('${attr(p.cover)}')`:""}"></div><div class="phone-avatar">${p.logo?`<img src="${attr(p.logo)}" alt="">`:esc((p.name||"B")[0])}</div><h2>${esc(p.name||"Your Business")}</h2><p>${esc(p.tagline||"Your tagline will appear here")}</p><div class="phone-actions"><span>Call</span><span>WhatsApp</span><span>Directions</span></div><div class="phone-block"></div><div class="phone-products"><i></i><i></i><i></i></div></div>`;}
window.suggestSlug=()=>{const input=document.querySelector("#bp-slug");if(input&&!input.dataset.touched)input.value=normalizeSlug(document.querySelector("#bp-name").value);};document.addEventListener("input",e=>{if(e.target?.id==="bp-slug")e.target.dataset.touched="1";});
function businessFormPayload(){const v=id=>document.querySelector(id)?.value.trim()||"";return {name:v("#bp-name"),slug:v("#bp-slug"),type:v("#bp-type"),tagline:v("#bp-tagline"),about:v("#bp-about"),phone:v("#bp-phone"),whatsapp:v("#bp-whatsapp"),email:v("#bp-email"),website:v("#bp-website"),address:v("#bp-address"),mapsUrl:v("#bp-maps"),hours:v("#bp-hours"),whatsappMessage:v("#bp-wa-message"),products:parseLines(v("#bp-products"),"product"),services:parseLines(v("#bp-services"),"service"),offers:parseLines(v("#bp-offers"),"offer"),brochure:v("#bp-brochure"),googleReview:v("#bp-review"),upi:v("#bp-upi"),logo:v("#bp-logo"),cover:v("#bp-cover"),socials:{instagram:v("#bp-instagram"),facebook:v("#bp-facebook"),youtube:v("#bp-youtube")},branding:{enabled:document.querySelector("#bp-brand-enabled").checked,accent:v("#bp-accent"),background:v("#bp-background"),buttonStyle:"soft",layout:"modern"},leadCapture:{enabled:document.querySelector("#bp-lead-enabled").checked,title:"Send an enquiry",askEmail:document.querySelector("#bp-lead-email").checked,askMessage:document.querySelector("#bp-lead-message").checked},published:document.querySelector("#bp-published").checked};}
window.saveBusiness=async id=>{try{let profile=await saveBusinessProfile(session.user,businessFormPayload(),id);const logoFile=document.querySelector("#bp-logo-file")?.files?.[0],coverFile=document.querySelector("#bp-cover-file")?.files?.[0];if(logoFile||coverFile){const patch={...profile};if(logoFile)patch.logo=await uploadBusinessAsset(session.user,profile.id,"logo",logoFile);if(coverFile)patch.cover=await uploadBusinessAsset(session.user,profile.id,"cover",coverFile);profile=await saveBusinessProfile(session.user,patch,profile.id);}toast("Business Profile saved.","success");route(`/business/${profile.id}`);}catch(e){toast(friendlyError(e),"error");}};
window.removeBusiness=async id=>{if(!confirm("Delete this Business Profile?"))return;try{await deleteBusinessProfile(session.user,id);toast("Business Profile deleted.","success");route("/business-profiles");}catch(e){toast(friendlyError(e),"error");}};
window.downloadBusinessQr=id=>{const p=state.profiles.find(x=>x.id===id);if(!p)return;const url=`${QRAJN.productionOrigin}/b/${p.slug}`,svg=qrSvg(url,{size:1000,margin:4,fg:"#0f172a",bg:"#ffffff",ec:"Q"});downloadBlob(new Blob([svg],{type:"image/svg+xml"}),`${safeName(p.name)}_Business_Profile_QR.svg`);};

async function publicBusinessPage(slug){app.innerHTML=`<div class="boot"><div class="spinner"></div></div>`;try{const p=await resolveBusinessProfile(slug);if(!p||p.published!==true){app.innerHTML=publicNotFound();return;}trackBusinessEvent(p,"view").catch(()=>{});app.innerHTML=publicProfileHtml(p);}catch(e){app.innerHTML=publicNotFound();}}
function actionUrl(p,type){if(type==="call")return `tel:${p.phone}`;if(type==="whatsapp")return `https://wa.me/${String(p.whatsapp||p.phone||"").replace(/\D/g,"")}?text=${encodeURIComponent(p.whatsappMessage||"Hi, I found your business through QR AJN.")}`;if(type==="directions")return p.mapsUrl||`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.address||p.name)}`;if(type==="website")return p.website;return "";}
function publicProfileHtml(p){const accent=p.branding?.enabled?p.branding.accent:"#0f766e",bg=p.branding?.enabled?p.branding.background:"#f8fafc";const activeOffers=(p.offers||[]).filter(o=>o.active!==false&&(!o.expiresAt||new Date(o.expiresAt)>=new Date()));return `<div class="public-profile" style="--profile-accent:${attr(accent)};--profile-bg:${attr(bg)}"><header class="public-top"><a class="brand" href="/" data-route>${productBrand()}</a><button class="btn small" onclick="navigator.share?.({title:document.title,url:location.href})">Share</button></header><main class="public-profile-card"><div class="public-cover" style="${p.cover?`background-image:url('${attr(p.cover)}')`:""}"></div><div class="public-avatar">${p.logo?`<img src="${attr(p.logo)}" alt="${attr(p.name)} logo">`:esc((p.name||"B")[0])}</div><section class="public-identity"><span class="category">${esc(p.type)}</span><h1>${esc(p.name)}</h1><p>${esc(p.tagline||"")}</p></section><div class="public-actions">${p.phone?`<a href="${attr(actionUrl(p,"call"))}" onclick="trackProfileAction('${attr(p.slug)}','call')">${icons.phone}<b>Call</b></a>`:""}${p.whatsapp||p.phone?`<a href="${attr(actionUrl(p,"whatsapp"))}" target="_blank" onclick="trackProfileAction('${attr(p.slug)}','whatsapp')"><span class="wa-icon">W</span><b>WhatsApp</b></a>`:""}${p.address?`<a href="${attr(actionUrl(p,"directions"))}" target="_blank" onclick="trackProfileAction('${attr(p.slug)}','directions')">${icons.pin}<b>Directions</b></a>`:""}${p.website?`<a href="${attr(p.website)}" target="_blank" onclick="trackProfileAction('${attr(p.slug)}','website')">${icons.external}<b>Website</b></a>`:""}</div>${activeOffers.length?`<section class="public-section"><div class="section-label">Offers</div>${activeOffers.map(o=>`<div class="offer-card"><b>${esc(o.title)}</b><span>${esc(o.description)}</span>${o.expiresAt?`<small>Valid until ${fmtDate(o.expiresAt)}</small>`:""}</div>`).join("")}</section>`:""}${p.about?`<section class="public-section"><div class="section-label">About</div><p>${esc(p.about)}</p></section>`:""}${(p.products||[]).length?`<section class="public-section"><div class="section-label">Products</div><div class="product-grid">${p.products.filter(x=>x.available!==false).map(x=>`<article class="product-card">${x.image?`<img src="${attr(x.image)}" alt="${attr(x.name)}">`:`<div class="product-placeholder">${icons.building}</div>`}<div><h3>${esc(x.name)}</h3>${x.price?`<b>${esc(x.price)}</b>`:""}<p>${esc(x.description||"")}</p>${p.whatsapp||p.phone?`<a class="mini-action" target="_blank" href="${attr(actionUrl({...p,whatsappMessage:`Hi, I found ${x.name} on your QR AJN profile. Is it available?`},"whatsapp"))}" onclick="trackProfileAction('${attr(p.slug)}','whatsapp','${attr(x.id)}')">Enquire</a>`:""}</div></article>`).join("")}</div></section>`:""}${(p.services||[]).length?`<section class="public-section"><div class="section-label">Services</div>${p.services.map(s=>`<div class="service-row"><div><h3>${esc(s.name)}</h3><p>${esc(s.description||"")}</p></div><b>${esc(s.price||"")}</b></div>`).join("")}</section>`:""}<section class="public-section info-grid">${p.hours?`<div><span>Hours</span><b>${esc(p.hours)}</b></div>`:""}${p.address?`<div><span>Address</span><b>${esc(p.address)}</b></div>`:""}${p.email?`<div><span>Email</span><a href="mailto:${attr(p.email)}">${esc(p.email)}</a></div>`:""}${p.phone?`<div><span>Phone</span><a href="tel:${attr(p.phone)}">${esc(p.phone)}</a></div>`:""}</section>${p.brochure||p.googleReview||p.upi?`<section class="public-section public-links">${p.brochure?`<a href="${attr(p.brochure)}" target="_blank">View brochure / menu</a>`:""}${p.googleReview?`<a href="${attr(p.googleReview)}" target="_blank">Leave a Google review</a>`:""}${p.upi?`<a href="upi://pay?pa=${encodeURIComponent(p.upi)}&pn=${encodeURIComponent(p.name)}">Pay with UPI</a>`:""}</section>`:""}${p.leadCapture?.enabled!==false?leadForm(p):""}<div class="profile-powered">Created with QR AJN</div></main></div>`;}
function leadForm(p){return `<section class="public-section lead-form"><div class="section-label">${esc(p.leadCapture?.title||"Send an enquiry")}</div><form onsubmit="sendPublicLead(event,'${attr(p.slug)}')"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Phone</label><input name="phone" inputmode="tel" required></div></div>${p.leadCapture?.askEmail?`<div class="field"><label>Email</label><input name="email" type="email"></div>`:""}${p.leadCapture?.askMessage!==false?`<div class="field"><label>Message</label><textarea name="message"></textarea></div>`:""}<label class="consent"><input type="checkbox" name="consent" required> I agree to share these details with ${esc(p.name)}.</label><button class="btn primary full" type="submit">Send enquiry</button></form></section>`;}
window.trackProfileAction=async(slug,type,productId="")=>{try{const p=await resolveBusinessProfile(slug);if(p)trackBusinessEvent(p,type,{productId}).catch(()=>{});}catch{}};
window.sendPublicLead=async(e,slug)=>{e.preventDefault();const button=e.currentTarget.querySelector("button");button.disabled=true;try{const p=await resolveBusinessProfile(slug);if(!p)throw new Error("Business profile unavailable.");const fd=new FormData(e.currentTarget);await submitBusinessLead(p,{name:fd.get("name"),phone:fd.get("phone"),email:fd.get("email"),message:fd.get("message"),consent:fd.get("consent")==="on"});e.currentTarget.reset();toast("Enquiry sent successfully.","success");}catch(err){toast(friendlyError(err),"error");}finally{button.disabled=false;}};
function publicNotFound(){return `<div class="public-missing"><a class="brand" href="/" data-route>${productBrand()}</a><div class="card"><h1>Profile unavailable</h1><p>This business profile is private, unavailable or no longer exists.</p><button class="btn" onclick="route('/')">Go to QR AJN</button></div></div>`;}

function settingsPage(){return shell(`<main class="container"><div class="section-head"><div><span class="kicker">SETTINGS</span><h1 class="page-title">Workspace settings</h1><p class="subtitle">Control preferences and account-level data.</p></div></div><div class="settings-stack"><section class="card settings-card"><h2>Preferences</h2><div class="field"><label>Timezone</label><input id="setting-timezone" value="${attr(state.settings.timezone||"Asia/Kolkata")}"></div><label class="switch-row"><input type="checkbox" id="setting-notifications" ${checked(state.settings.emailNotifications!==false)}><span>Email notifications</span></label><button class="btn primary" onclick="saveSettingsNow()">Save preferences</button></section><section class="card settings-card info-card"><h2>Production readiness</h2><p>Secure password redirects, custom-domain verification and server-recorded advanced scans use the server endpoints included in this build. Configure the deployment environment variables in <code>PRODUCTION_SETUP.md</code> before enabling those features on the public domain.</p></section><section class="card settings-card danger-zone"><h2>Delete workspace data</h2><p>Deletes QR codes, scan events, profiles, leads, branding and preferences under your QR AJN workspace.</p><button class="btn danger" onclick="resetAll()">Delete workspace data</button></section></div></main>`);}
window.saveSettingsNow=async()=>{try{state.settings=await persistSettings(session.user,{timezone:document.querySelector("#setting-timezone").value.trim()||"Asia/Kolkata",emailNotifications:document.querySelector("#setting-notifications").checked});toast("Preferences saved.","success");}catch(e){toast(friendlyError(e),"error");}};
window.resetAll=async()=>{if(!confirm("Delete all QR AJN workspace data? This cannot be undone."))return;try{await resetWorkspace(session.user);toast("Workspace data deleted.","success");route("/dashboard");}catch(e){toast(friendlyError(e),"error");}};

function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast("Copied.","success")).catch(()=>toast("Copy failed.","error"));}window.copyText=copyText;
window.downloadCsv=id=>{try{const rows=state.events.filter(e=>e.qr_id===id),csv=["when,device,browser,os,language,timezone,referrer,screen",...rows.map(e=>[e.when,e.device,e.browser,e.os,e.language||"",e.timezone||"",e.referrer||"",e.screen||""].map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(","))].join("\n");downloadBlob(new Blob(["\ufeff",csv],{type:"text/csv;charset=utf-8"}),"QR_AJN_scan_analytics.csv");}catch(e){toast(friendlyError(e),"error");}};
window.downloadQR=(id,format)=>{const q=state.qrs.find(x=>x.id===id);if(!q)return;const svg=qrSvg(shortLink(q),{size:1200,margin:q.design?.quietZone||4,fg:q.design?.foreground||"#0f172a",bg:q.design?.background||"#fff",ec:q.design?.errorCorrection||"M"});if(format==="svg"){downloadBlob(new Blob([svg],{type:"image/svg+xml"}),`${safeName(q.name)}.svg`);return;}const img=new Image(),blob=new Blob([svg],{type:"image/svg+xml"}),url=URL.createObjectURL(blob);img.onload=()=>{const c=document.createElement("canvas");c.width=c.height=1200;const ctx=c.getContext("2d");ctx.fillStyle=q.design?.background||"#fff";ctx.fillRect(0,0,1200,1200);ctx.drawImage(img,0,0);URL.revokeObjectURL(url);const mime=format==="jpg"?"image/jpeg":format==="webp"?"image/webp":"image/png",ext=format==="jpg"?"jpg":format==="webp"?"webp":"png";c.toBlob(b=>downloadBlob(b,`${safeName(q.name)}.${ext}`),mime,.96);};img.src=url;};
function downloadBlob(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

function chooseClientDestination(link){let destination=link.destination;const now=Date.now();if(link.expiry?.enabled){if(link.expiry.at&&new Date(link.expiry.at).getTime()<=now)return link.expiry.expiredDestination||"";if(Number(link.expiry.maxScans||0)>0&&Number(link.scanCount||0)>=Number(link.expiry.maxScans))return link.expiry.expiredDestination||"";}if(link.schedule?.enabled){const start=link.schedule.startAt?new Date(link.schedule.startAt).getTime():0,end=link.schedule.endAt?new Date(link.schedule.endAt).getTime():Infinity;if(now<start||now>end)return link.schedule.outsideDestination||"";}if(link.smartTargeting?.enabled){const ua=navigator.userAgent||"",device=/Android/i.test(ua)?"device:android":/iPhone|iPad/i.test(ua)?"device:ios":"device:desktop",lang=(navigator.language||"").toLowerCase();const r=(link.smartTargeting.rules||[]).find(x=>x.field===device)||(link.smartTargeting.rules||[]).find(x=>x.field==="language"&&lang.startsWith(String(x.value||"").toLowerCase()));if(r?.destination)destination=r.destination;else if(link.smartTargeting.fallbackDestination)destination=link.smartTargeting.fallbackDestination;}if(link.utm?.enabled&&destination){try{const u=new URL(destination);for(const [k,v] of [["utm_source",link.utm.source],["utm_medium",link.utm.medium],["utm_campaign",link.utm.campaign],["utm_term",link.utm.term],["utm_content",link.utm.content]])if(v)u.searchParams.set(k,v);destination=u.toString();}catch{}}return destination;}
async function runClientRedirect(){const shortId=decodeURIComponent(location.pathname.split("/")[2]||"").trim();app.innerHTML=redirectShell("Finding destination…");try{const resolved=await resolvePublicLink(shortId);if(!resolved){app.innerHTML=redirectShell("This QR code is inactive or unavailable.",true);return;}if(resolved.link.passwordProtected||resolved.link.leadCapture?.enabled){app.innerHTML=redirectShell("This QR uses secure campaign controls. Deploy with the included server redirect setup to enforce password or lead capture.",true);return;}const destination=chooseClientDestination(resolved.link);if(!destination){app.innerHTML=redirectShell("This QR is currently unavailable because of its expiry or schedule settings.",true);return;}trackPublicScan(shortId,resolved.link).catch(()=>{});setTimeout(()=>location.replace(destination),350);}catch(e){app.innerHTML=redirectShell("Unable to open this QR right now.",true);}}
function redirectShell(message,error=false){return `<div class="redirect-shell"><div class="redirect-card">${productBrand()}<div class="redirect-icon ${error?"error":""}">${icons.qr}</div><h1>${error?"QR unavailable":"Opening your QR"}</h1><p>${esc(message)}</p>${error?`<a class="btn" href="/">Go to QR AJN</a>`:`<div class="redirect-progress"><span></span></div>`}</div></div>`;}

function render(){const p=location.pathname;if(/^\/b\/[^/]+$/.test(p)){publicBusinessPage(decodeURIComponent(p.split("/")[2]));return;}if(protectedPath(p)&&!session){history.replaceState({},"","/auth");app.innerHTML=authPage();return;}if(p==="/")app.innerHTML=landing();else if(p==="/auth")app.innerHTML=session?dashboard():authPage();else if(p==="/dashboard")app.innerHTML=dashboard();else if(p==="/qr-codes")app.innerHTML=qrList();else if(/^\/qr\/[^/]+$/.test(p))app.innerHTML=qrDetail(decodeURIComponent(p.split("/")[2]));else if(p==="/create")app.innerHTML=createPage();else if(p==="/branding")app.innerHTML=brandingPage();else if(p==="/business-profiles")app.innerHTML=businessProfilesPage();else if(p==="/business/new")app.innerHTML=businessEditor("");else if(/^\/business\/[^/]+$/.test(p))app.innerHTML=businessEditor(decodeURIComponent(p.split("/")[2]));else if(p==="/settings")app.innerHTML=settingsPage();else app.innerHTML=shell(`<main class="container"><div class="empty-card"><h2>Page not found</h2><button class="btn" onclick="route('${session?"/dashboard":"/"}')">Go back</button></div></main>`);window.scrollTo({top:0,behavior:"instant"});if(p==="/create")setTimeout(updateCreatePreview,0);}

(async function init(){try{if(/^\/r\/[^/]+$/.test(location.pathname)){await runClientRedirect();return;}await waitForAuthReady();authUnsubscribe=onAccountChanged(async user=>{session=user?{user}:null;if(user){try{await loadState();connectLive();}catch(e){toast(friendlyError(e),"error");}}else{if(liveUnsubscribe){liveUnsubscribe();liveUnsubscribe=null;}state={qrs:[],events:[],branding:{...DEFAULT_BRANDING},settings:{...DEFAULT_SETTINGS},profiles:[],businessEvents:[],leads:[],qrLeads:[]};}if(protectedPath()&&!session)history.replaceState({},"","/auth");render();});render();}catch(e){app.innerHTML=`<div class="boot"><div class="startup-error"><img src="/assets/qr-ajn-logo.svg" alt="QR AJN"><h2>QR AJN could not start</h2><p>${esc(friendlyError(e))}</p><p>Check your internet connection and deployment configuration.</p></div></div>`;}})();
